def remove_n_elems_from_index(t: tuple, n: int, i: int) -> tuple:
    # If the start index is out of bounds, return the tuple unchanged.
    if i < 0 or i >= len(t):
        return t
    # Keep everything before index i and everything from index i + n onward.
    return t[:i] + t[i + n:]

from collections import Counter

def first_non_repeating_char(s: str):
    # Count how many times each character appears.
    counts = Counter(s)
    # Return the first character whose count is exactly 1.
    for ch in s:
        if counts[ch] == 1:
            return ch
    return None

