def difference(data: list) -> list:
    # Differences between each pair of consecutive elements.
    return [data[i + 1] - data[i] for i in range(len(data) - 1)]

def nth_order_difference(data: list, n: int) -> list:
    # Apply difference() n times.
    result = data
    for _ in range(n):
        result = difference(result)
    return result

def has_positive_trend(data: list) -> bool:
    # Positive trend means every consecutive difference is positive.
    return all(d > 0 for d in difference(data))

def moving_average(data: list, window_size: int) -> list:
    # Average of each sliding window of the given size.
    return [sum(data[i:i + window_size]) / window_size
            for i in range(len(data) - window_size + 1)]

def has_negative_average_trend(data: list, window_size: int) -> bool:
    # Negative trend means every consecutive difference of the
    # moving averages is negative.
    ma = moving_average(data, window_size)
    return all(d < 0 for d in difference(ma))
